  const [kpis, setKpis] = useState<KPI[]>([]);
  const [currentUser, setCurrentUser] = useState<Personnel | null>(null);
  const [appConfig, setAppConfig] = useState<AppConfig>(INITIAL_CONFIG);
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [showSlowConnMsg, setShowSlowConnMsg] = useState(false);

  const t = DICTIONARY[lang];

  const setView = (newView: ViewState) => {
    setViewState(newView);
    localStorage.setItem(STORAGE_KEYS.VIEW, newView);
  };

  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr';
  }, [lang]);

  // Session Restoration
  useEffect(() => {
    const storedUser = localStorage.getItem(STORAGE_KEYS.USER);
    const storedView = localStorage.getItem(STORAGE_KEYS.VIEW);
    if (storedUser) {
        try {
            setCurrentUser(JSON.parse(storedUser));
            if (storedView) setViewState(storedView as ViewState);
        } catch (e) { localStorage.removeItem(STORAGE_KEYS.USER); }
    }
  }, []);

  // Data Subscriptions
  useEffect(() => {
    const slowTimer = setTimeout(() => {
        if (isLoadingData) setShowSlowConnMsg(true);
    }, 6000);

    const unsubTickets = subscribeToTickets((data) => {
      setTickets(data);
      setIsLoadingData(false);
    });

    const unsubCustomers = subscribeToCustomers(setCustomers);
    const unsubMessages = subscribeToMessages(setMessages);
    const unsubTasks = subscribeToTasks(setTasks);
    const unsubMeetings = subscribeToMeetings(setMeetings);
    const unsubKPIs = subscribeToKPIs(setKpis);

    const unsubSettings = subscribeToSettings(
      (cfg) => { if (cfg) setAppConfig(cfg); },
      (srv) => { if (srv) setServices(srv); },
      (ppl) => { if (ppl) setPersonnel(ppl); }
    );

    return () => {
      unsubTickets(); unsubCustomers(); unsubSettings();
      unsubMessages(); unsubTasks(); unsubMeetings(); unsubKPIs();
      clearTimeout(slowTimer);
    };
  }, []);

  const handleLogin = async (u: string, p: string): Promise<boolean> => {
    const user = personnel.find(person => person.username === u && person.password === p);
    if (user) {
      setCurrentUser(user);
      localStorage.setItem(STORAGE_KEYS.USER, JSON.stringify(sanitizeData(user)));
      return true;
    }
    return false;
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setView('landing');
    localStorage.removeItem(STORAGE_KEYS.USER);
  };

  const handleNewTicket = async (ticketOrTickets: Ticket | Ticket[]) => {
      const list = Array.isArray(ticketOrTickets) ? ticketOrTickets : [ticketOrTickets];
      for (const t of list) { await saveTicketToCloud(t); }
  };

  const NavItem = ({ active, label, icon, onClick }: any) => (
    <button onClick={onClick} className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all ${active ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-600 hover:bg-gray-100'}`}>
      {icon} <span className="font-medium">{label}</span>
    </button>
  );

  return (
    <div className={`min-h-screen bg-gray-50 flex flex-col font-sans ${lang === 'fa' ? 'font-vazir' : ''}`} dir={lang === 'fa' ? 'rtl' : 'ltr'}>
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('landing')}>
            <div className="bg-indigo-600 text-white p-2 rounded-lg"><IconShield className="w-6 h-6" /></div>
            <div>
              <h1 className="text-xl font-bold text-gray-900">{lang === 'fa' ? appConfig.appTitle : appConfig.appTitleEn}</h1>
              <p className="text-xs text-gray-500">{lang === 'fa' ? appConfig.appSubtitle : appConfig.appSubtitleEn}</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <nav className="hidden md:flex gap-2">
              <NavItem active={view === 'new-ticket'} label={t.newTicket} icon={<IconPlus className="w-4 h-4" />} onClick={() => setView('new-ticket')} />
              <NavItem active={view === 'tracking'} label={t.tracking} icon={<IconSearch className="w-4 h-4" />} onClick={() => setView('tracking')} />
              <NavItem active={view === 'admin'} label={t.expertPanel} icon={<IconLayout className="w-4 h-4" />} onClick={() => setView('admin')} />
            </nav>
            <div className="flex border border-gray-200 rounded-lg overflow-hidden">
               <button onClick={() => setLang('fa')} className={`px-3 py-1 text-xs font-bold ${lang === 'fa' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-400'}`}>FA</button>
               <button onClick={() => setLang('en')} className={`px-3 py-1 text-xs font-bold ${lang === 'en' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-400'}`}>EN</button>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-grow p-4 md:p-8 max-w-7xl mx-auto w-full">
        {/* LANDING VIEW */}
        {view === 'landing' && (
          <div className="animate-fade-in text-center py-16">
              <h2 className="text-4xl md:text-6xl font-black text-gray-900 mb-6 leading-tight">{lang === 'fa' ? (appConfig.landingHeroTitle || 'مسیر جهانی شدن کسب‌وکار شما') : 'Globalize Your Business'}</h2>
              <p className="text-xl text-gray-600 mb-12 max-w-2xl mx-auto leading-relaxed">{lang === 'fa' ? (appConfig.landingHeroSubtitle || t.landingSubtitle) : t.landingSubtitle}</p>
              <div className="flex flex-col sm:flex-row gap-4 justify-center">
                <button onClick={() => setView('new-ticket')} className="px-8 py-4 bg-indigo-600 text-white rounded-xl text-lg font-bold shadow-xl hover:scale-105 transition-transform">{t.startBtn}</button>
                <button onClick={() => setView('tracking')} className="px-8 py-4 bg-white text-gray-700 border border-gray-200 rounded-xl text-lg font-bold hover:bg-gray-50 transition-colors">{t.trackBtn}</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-24">
                {t.features.map((f, i) => (
                  <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                      <div className="text-4xl mb-4">{[ '📂', '🌍', '📊'][i]}</div>
                      <h3 className="font-bold text-lg mb-2">{f.title}</h3>
                      <p className="text-gray-500 text-sm">{f.desc}</p>
                  </div>
                ))}
              </div>
          </div>
        )}

        {/* NEW TICKET VIEW */}
        {view === 'new-ticket' && (
          <CustomerForm 
            config={appConfig}
            services={services.filter(s => s.isActive)} 
            onSubmit={handleNewTicket}
            onCancel={() => setView('landing')}
            onGoToTracking={() => setView('tracking')}
            lang={lang}
          />
        )}

        {/* TRACKING VIEW */}
        {view === 'tracking' && <TrackingView tickets={tickets} services={services} lang={lang} />}

        {/* ADMIN/EXPERT PANEL VIEW */}
        {view === 'admin' && (
          <>
            {!currentUser ? (
              <LoginView onLogin={handleLogin} onBack={() => setView('landing')} />
            ) : (
              // Inside Dashboard, show loader only if data is not ready
              isLoadingData ? (
                <div className="flex flex-col items-center justify-center h-96 gap-4">
                    <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                    <div className="text-gray-600 font-bold">{t.loadingData}</div>
                    {showSlowConnMsg && (
                        <div className="text-center animate-fade-in">
                            <p className="text-amber-600 text-xs mb-4">{t.connectionNote}</p>
                            <button onClick={() => setIsLoadingData(false)} className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-lg text-sm text-gray-500 hover:bg-gray-50">
                                <IconRefreshCw className="w-4 h-4" /> {t.retry}
                            </button>
                        </div>
                    )}
                </div>
              ) : (
                <AdminDashboard 
                  lang={lang} currentUser={currentUser} tickets={tickets} services={services} personnel={personnel} 
                  customers={customers} messages={messages} tasks={tasks} meetings={meetings} kpis={kpis} config={appConfig}
                  onCreateTicket={async (t) => handleNewTicket(t)} 
                  onUpdateTicket={(id, updates, actor, note) => updateTicketInCloud(id, updates)}
                  onDeleteTicket={deleteTicketFromCloud}
                  onUpdateServices={saveServicesToCloud}
                  onUpdatePersonnel={savePersonnelToCloud}
                  onUpdateCustomers={saveCustomersBulkToCloud}
                  onEditCustomer={updateCustomerInCloud}
                  onDeleteCustomer={deleteCustomerFromCloud}
                  onUpdateConfig={saveAppConfigToCloud}
                  onLogout={handleLogout}
                />
              )
            )}
          </>
        )}
      </main>

      <footer className="bg-white border-t border-gray-200 py-8 text-center text-gray-500 text-sm">
        <p>{appConfig.footerText || t.footer}</p>
      </footer>
    </div>
  );
};

export default App;
